package br.com.confirmacao.professional.location.api;
import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.professional.location.application.ProfessionalLocationService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/professionals/me/location") public class ProfessionalLocationController{private final ProfessionalLocationService service;private final AuditService audit;public ProfessionalLocationController(ProfessionalLocationService s,AuditService a){service=s;audit=a;}@GetMapping public ProfessionalLocationResponse get(JwtAuthenticationToken jwt){return ProfessionalLocationResponse.from(service.find(id(jwt)));}@PutMapping public ProfessionalLocationResponse save(JwtAuthenticationToken jwt,@Valid @RequestBody ProfessionalLocationRequest request,HttpServletRequest http){var id=id(jwt);var location=service.save(id,request.city(),request.state(),request.timezone());audit.record(AuditAction.PROFESSIONAL_UPDATED,"PROFESSIONAL",id,http);return ProfessionalLocationResponse.from(location);}private UUID id(JwtAuthenticationToken jwt){return UUID.fromString(jwt.getToken().getClaimAsString("professional_id"));}}
